extends SceneTree
## External inspection of disposable scenes; capture mode releases only validation metadata.
var game: Node3D
var settings: Node
var triangle_cache: Dictionary = {}
var records: Array[Dictionary] = []
var capture_authoring := false
var mesh_probe: Dictionary = {}
var validation_scripts: Array[Script] = []
var capture_release: Dictionary = {}

func _initialize() -> void:
	_run.call_deferred()

func _run() -> void:
	mesh_probe = _probe_mesh_getters()
	if not mesh_probe.native_mesh_arrays_and_bounds:
		push_error("Native mesh inspection is unavailable; no structural result is asserted")
		quit(2)
		return
	capture_authoring = OS.get_cmdline_user_args().has("--capture-authoring")
	if capture_authoring:
		var decoration = load("res://scripts/visual/abyss_decoration.gd")
		decoration.capture_geometry_for_validation = true
		validation_scripts.append(decoration)
		set_meta("capture_city_scenery_geometry", true)
	settings = root.get_node("VisualSettings")
	settings.storage_path = OS.get_environment("XDG_CONFIG_HOME").path_join("audit-graphics.cfg")
	if not settings.set_options(1, 60):
		push_error("Cannot set Medium startup quality")
		quit(4)
		return
	var started := Time.get_ticks_usec()
	var packed := load("res://scenes/main.tscn") as PackedScene
	game = packed.instantiate() as Node3D
	root.add_child(game)
	current_scene = game
	while game.current_location != &"sanctuary" or game.transitioning:
		await physics_frame
	var startup_ms := float(Time.get_ticks_usec() - started) / 1000.0
	for quality in range(3):
		if not settings.set_options(quality, 60) or int(settings.snapshot().quality) != quality:
			push_error("Requested quality was not applied")
			quit(4)
			return
		await process_frame
		await process_frame
		_refresh_presentations(game.active_world)
		var row := _sample(game.active_world)
		row.quality = quality
		row.location = "sanctuary"
		var landscape: Node = game.active_world.get_node_or_null("SanctuaryLandscape")
		if landscape != null:
			row.landscape = _clean(landscape.get_scenery_snapshot())
			row.landscape_actual = _sample(landscape)
			row.panorama_actual = _panorama(game.active_world)
			if capture_authoring and not row.panorama_actual.bounds_available_from_construction_records:
				push_error("Opt-in panorama construction records are unavailable")
				quit(3)
				return
		var ambience: Node = game.active_world.get_node_or_null("SanctuaryAmbience")
		if ambience != null:
			row.ambience = _clean(ambience.get_presentation_snapshot())
			row.ambience_actual = _sample(ambience)
			row.actor_refresh_us = _time_calls(Callable(ambience, "_refresh_activity"))
		var fauna: Node = game.active_world.get_node_or_null("AmbientFaunaBudget")
		if fauna != null:
			fauna.refresh()
			row.fauna = _clean(fauna.snapshot())
			row.fauna_refresh_us = _time_calls(Callable(fauna, "refresh"))
		records.append(row)
	if capture_authoring:
		capture_release.sanctuary = _measure_capture_release(game.active_world)
	await game.start_expedition(23)
	for quality in range(3):
		if not settings.set_options(quality, 60) or int(settings.snapshot().quality) != quality:
			push_error("Requested quality was not applied")
			quit(4)
			return
		await process_frame
		await process_frame
		_refresh_presentations(game.active_world)
		var row := _sample(game.active_world)
		row.quality = quality
		row.location = "rootbound_abyss_seed_23"
		row.rooms = game.active_world.rooms.size()
		var fauna: Node = game.active_world.get_node_or_null("AmbientFaunaBudget")
		if fauna != null:
			fauna.refresh()
			row.fauna = _clean(fauna.snapshot())
			row.fauna_refresh_us = _time_calls(Callable(fauna, "refresh"))
		records.append(row)
	if capture_authoring:
		capture_release.rootbound_abyss_seed_23 = _measure_capture_release(game.active_world)
	print("LIVING STRUCTURAL AUDIT: ", JSON.stringify({"medium_startup_including_fade_ms": startup_ms, "capture_release": capture_release, "version": ProjectSettings.get_setting("application/config/version"), "capture_authoring": capture_authoring, "mesh_probe": mesh_probe, "records": records}))
	game.queue_free()
	await process_frame
	await create_timer(0.2).timeout
	for resource: Script in validation_scripts:
		resource.capture_geometry_for_validation = false
	validation_scripts.clear()
	quit(0)

func _sample(node: Node) -> Dictionary:
	var result := {"nodes": 0, "processing_nodes": 0, "physics_processing_nodes": 0, "mesh_nodes_with_geometry": 0, "multimesh_batches": 0, "retained_instances": 0, "enabled_instances": 0, "retained_instanced_triangles": 0, "enabled_instanced_triangles": 0, "collision_objects": 0, "collision_shapes": 0, "lights": 0, "environments": 0, "audio_players": 0, "label_3d_nodes": 0, "retained_triangle_unmeasured_instances": 0, "enabled_triangle_unmeasured_instances": 0, "authored_transform_records": 0, "validation_only_transform_records": 0, "fauna_canonical_records": 0, "static_allocator_bytes": Performance.get_monitor(Performance.MEMORY_STATIC)}
	_collect(node, result)
	return result

func _collect(node: Node, result: Dictionary) -> void:
	result.nodes += 1
	result.processing_nodes += int(node.can_process() and node.is_processing())
	result.physics_processing_nodes += int(node.can_process() and node.is_physics_processing())
	result.collision_objects += int(node is CollisionObject3D)
	result.collision_shapes += int(node is CollisionShape3D)
	result.lights += int(node is Light3D)
	result.environments += int(node is WorldEnvironment)
	result.audio_players += int(node is AudioStreamPlayer or node is AudioStreamPlayer3D)
	result.label_3d_nodes += int(node is Label3D)
	for key: StringName in [&"authored_transforms", &"authored_instance_transforms", &"authored_instances"]:
		if node.has_meta(key):
			result.authored_transform_records += node.get_meta(key).size()
			result.validation_only_transform_records += node.get_meta(key).size()
	if node.is_in_group("ambient_fauna_regions"):
		var authored: Array = node.get("authored_instances")
		result.authored_transform_records += authored.size()
		result.fauna_canonical_records += authored.size()
	if node is MeshInstance3D and node.mesh != null:
		var triangles := _triangles(node.mesh)
		result.mesh_nodes_with_geometry += 1
		result.retained_instances += 1
		result.retained_instanced_triangles += maxi(triangles, 0)
		result.retained_triangle_unmeasured_instances += int(triangles < 0)
		if node.is_visible_in_tree():
			result.enabled_instances += 1
			result.enabled_instanced_triangles += maxi(triangles, 0)
			result.enabled_triangle_unmeasured_instances += int(triangles < 0)
	elif node is MultiMeshInstance3D and node.multimesh != null and node.multimesh.mesh != null:
		var triangles := _triangles(node.multimesh.mesh)
		var retained: int = node.multimesh.instance_count
		var active: int = node.multimesh.visible_instance_count if node.multimesh.visible_instance_count >= 0 else retained
		result.multimesh_batches += 1
		result.retained_instances += retained
		result.retained_instanced_triangles += maxi(triangles, 0) * retained
		result.retained_triangle_unmeasured_instances += retained if triangles < 0 else 0
		if node.is_visible_in_tree():
			result.enabled_instances += active
			result.enabled_instanced_triangles += maxi(triangles, 0) * active
			result.enabled_triangle_unmeasured_instances += active if triangles < 0 else 0
	for child: Node in node.get_children():
		_collect(child, result)

func _triangles(mesh: Mesh) -> int:
	# ImmediateMesh has no public topology getter and is not covered by the
	# native ArrayMesh probe. Count its instances separately, never guess.
	if mesh is ImmediateMesh: return -1
	var id := mesh.get_instance_id()
	if triangle_cache.has(id): return triangle_cache[id]
	var total := 0
	for surface in range(mesh.get_surface_count()):
		if mesh is ArrayMesh and mesh.surface_get_primitive_type(surface) != Mesh.PRIMITIVE_TRIANGLES:
			return -1
		var arrays := mesh.surface_get_arrays(surface)
		var indices: Variant = arrays[Mesh.ARRAY_INDEX]
		var vertices: PackedVector3Array = arrays[Mesh.ARRAY_VERTEX]
		total += (indices.size() if indices != null and not indices.is_empty() else vertices.size()) / 3
	triangle_cache[id] = total
	return total

func _panorama(world: Node3D) -> Dictionary:
	var count := 0
	var minimum_radius := INF
	var triangles := 0
	var enabled := 0
	var bounds_available := true
	for node: Node3D in get_nodes_in_group("city_scenery_panorama"):
		if not world.is_ancestor_of(node): continue
		count += 1
		if node is MeshInstance3D:
			minimum_radius = minf(minimum_radius, _radius(node.global_transform * node.mesh.get_aabb()))
			triangles += _triangles(node.mesh)
			enabled += _triangles(node.mesh)
		elif node is MultiMeshInstance3D:
			var active: int = node.multimesh.visible_instance_count if node.multimesh.visible_instance_count >= 0 else node.multimesh.instance_count
			var authored: Array = node.get_meta("authored_instance_transforms", [])
			bounds_available = bounds_available and authored.size() == node.multimesh.instance_count
			for transform: Transform3D in authored:
				var bounds: AABB = node.global_transform * (transform * node.multimesh.mesh.get_aabb())
				minimum_radius = minf(minimum_radius, _radius(bounds))
			triangles += _triangles(node.multimesh.mesh) * node.multimesh.instance_count
			enabled += _triangles(node.multimesh.mesh) * active
	return {"batches": count, "bounds_available_from_construction_records": bounds_available, "minimum_recorded_mesh_radius": minimum_radius if bounds_available else -1.0, "retained_triangles": triangles, "enabled_triangles": enabled}

func _probe_mesh_getters() -> Dictionary:
	var mesh := ArrayMesh.new()
	var arrays := []
	arrays.resize(Mesh.ARRAY_MAX)
	var vertices := PackedVector3Array([Vector3.ZERO, Vector3(2, 0, 0), Vector3(0, 3, 4)])
	arrays[Mesh.ARRAY_VERTEX] = vertices
	mesh.add_surface_from_arrays(Mesh.PRIMITIVE_TRIANGLES, arrays)
	var native_ok: bool = mesh.surface_get_arrays(0)[Mesh.ARRAY_VERTEX] == vertices and mesh.get_aabb().position.is_equal_approx(Vector3.ZERO) and mesh.get_aabb().size.is_equal_approx(Vector3(2, 3, 4)) and _triangles(mesh) == 1 and _triangles(BoxMesh.new()) == 12
	var multi := MultiMesh.new()
	multi.transform_format = MultiMesh.TRANSFORM_3D
	multi.mesh = mesh
	multi.instance_count = 1
	var authored := Transform3D(Basis.IDENTITY, Vector3(17, 5, -9))
	multi.set_instance_transform(0, authored)
	return {"native_mesh_arrays_and_bounds": native_ok, "multimesh_transform_readback_matches": multi.get_instance_transform(0).is_equal_approx(authored), "multimesh_buffer_size": multi.buffer.size(), "multimesh_count_retained": multi.instance_count}

func _radius(bounds: AABB) -> float:
	return Vector2(clampf(0.0, bounds.position.x, bounds.end.x), clampf(0.0, bounds.position.z, bounds.end.z)).length()

func _time_calls(callback: Callable) -> Dictionary:
	for index in range(10): callback.call()
	var samples: Array[int] = []
	for index in range(100):
		var started := Time.get_ticks_usec()
		callback.call()
		samples.append(Time.get_ticks_usec() - started)
	samples.sort()
	return {"sample_count": 100, "samples_us": samples, "median": samples[50], "p95": samples[94], "minimum": samples[0], "maximum": samples[99]}

func _clean(value: Variant) -> Variant:
	if value is Dictionary:
		var result := {}
		for key: Variant in value: result[key] = _clean(value[key])
		return result
	if value is Array:
		var result := []
		for item: Variant in value: result.append(_clean(item))
		return result
	if value is Vector3: return [value.x, value.y, value.z]
	if value is AABB: return {"position": _clean(value.position), "size": _clean(value.size)}
	return value

func _measure_capture_release(world: Node) -> Dictionary:
	var counted := _sample(world)
	var before := int(Performance.get_monitor(Performance.MEMORY_STATIC))
	_discard_validation_arrays(world)
	var after := int(Performance.get_monitor(Performance.MEMORY_STATIC))
	return {"validation_transform_records_released": counted.validation_only_transform_records, "canonical_fauna_records_retained": counted.fauna_canonical_records, "static_allocator_before": before, "static_allocator_after": after, "static_allocator_released_bytes": before - after}

func _discard_validation_arrays(node: Node) -> void:
	for key: StringName in [&"authored_transforms", &"authored_instance_transforms"]:
		if node.has_meta(key): node.remove_meta(key)
	for child: Node in node.get_children(): _discard_validation_arrays(child)

func _refresh_presentations(world: Node) -> void:
	var ambience: Node = world.get_node_or_null("SanctuaryAmbience")
	if ambience != null: ambience._refresh_activity()
	var fauna: Node = world.get_node_or_null("AmbientFaunaBudget")
	if fauna != null: fauna.refresh()
